import os
import chardet
class FileHandler:
    """文件处理工具类，处理不同格式的小说文件读取"""

    def __init__(self):
        self.supported_formats = ['.txt', '.epub', '.mobi', '.pdf']

    def detect_encoding(self, file_path):
        """检测文件编码"""
        with open(file_path, 'rb') as f:
            raw_data = f.read(10000)
            result = chardet.detect(raw_data)
            return result['encoding']

    def read_txt(self, file_path):
        """读取TXT文件"""
        encoding = self.detect_encoding(file_path)
        try:
            with open(file_path, 'r', encoding=encoding) as f:
                return f.read()
        except UnicodeDecodeError:
            # 检测失败尝试常见编码
            for enc in ['utf-8', 'gbk', 'gb2312', 'latin-1']:
                try:
                    with open(file_path, 'r', encoding=enc) as f:
                        return f.read()
                except UnicodeDecodeError:
                    continue
        raise Exception(f"无法解码文件 {file_path}，尝试了多种编码都失败")

    def read_epub(self, file_path):
        """读取EPUB文件，提取文本内容"""
        try:
            import zipfile
            from bs4 import BeautifulSoup

            text_content = []
            with zipfile.ZipFile(file_path, 'r') as zf:
                # 查找HTML内容文件
                for name in zf.namelist():
                    if name.endswith('.html') or name.endswith('.xhtml'):
                        with zf.open(name) as f:
                            soup = BeautifulSoup(f.read(), 'html.parser')
                            # 提取所有文本段落
                            paragraphs = soup.find_all('p')
                            for p in paragraphs:
                                text = p.get_text().strip()
                                if text:
                                    text_content.append(text)

            return '\n\n'.join(text_content)
        except ImportError:
            return "错误：需要安装 beautifulsoup4 库才能支持EPUB格式\n" + self._demo_content(file_path)

    def read_mobi(self, file_path):
        """读取MOBI文件"""
        # 简单处理说明，实际需要依赖mobi库
        return f"[MOBI文件] {os.path.basename(file_path)}\n完整支持需要安装mobi解析库，当前仅占位显示。\n"

    def read_pdf(self, file_path):
        """读取PDF文件"""
        try:
            from PyPDF2 import PdfReader
            reader = PdfReader(file_path)
            text_content = []
            for page in reader.pages:
                text = page.extract_text()
                if text:
                    text_content.append(text)
            return '\n\n'.join(text_content)
        except ImportError:
            return "错误：需要安装 PyPDF2 库才能支持PDF格式\n" + self._demo_content(file_path)

    def _demo_content(self, file_path):
        return f"\n文件路径: {file_path}\n请安装对应依赖库以支持此格式。"

    def read_file(self, file_path):
        """根据文件扩展名选择读取方式"""
        ext = os.path.splitext(file_path)[1].lower()

        if ext == '.txt':
            return self.read_txt(file_path)
        elif ext == '.epub':
            return self.read_epub(file_path)
        elif ext == '.mobi':
            return self.read_mobi(file_path)
        elif ext == '.pdf':
            return self.read_pdf(file_path)
        else:
            # 默认按txt处理
            return self.read_txt(file_path)

import re
class TextProcessor:
    """文本处理工具类，提供文本清理优化功能"""

    def clean_text(self, text):
        """清理文本：去多余空行、去广告杂质、去乱码"""
        # 移除多余空行（超过2个空行变成1个）
        cleaned = re.sub(r'\n\s*\n', '\n\n', text)

        # 移除常见广告水印
        ad_patterns = [
            r'网站:.*\n',
            r'网址:.*\n',
            r'更多.*请访问.*\n',
            r'.*手打小说网.*\n',
            r'.*更新最快.*\n',
            r'本章未完.*\n',
        ]
        for pattern in ad_patterns:
            cleaned = re.sub(pattern, '', cleaned, flags=re.IGNORECASE)

        # 移除乱码控制字符
        cleaned = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]', '', cleaned)

        # 去掉首尾空白
        cleaned = cleaned.strip()

        return cleaned

    def simple_to_traditional(self, text):
        """简体转繁体（简单实现，完整版需要opencc）"""
        # 这里用一个简单的映射示例，实际建议使用opencc库
        simple_map = {
            '为': '為', '会': '會', '可以': '可以',
            # 实际完整转换需要字典，这里占位
        }
        result = text
        for s, t in simple_map.items():
            result = result.replace(s, t)
        return result

    def traditional_to_simple(self, text):
        """繁体转简体"""
        traditional_map = {
            '為': '为', '會': '会',
        }
        result = text
        for t, s in traditional_map.items():
            result = result.replace(t, s)
        return result

    def batch_replace(self, text, replacements):
        """批量替换文本
        replacements: 字典 {old: new}
        """
        result = text
        for old, new in replacements.items():
            result = result.replace(old, new)
        return result

    def detect_chapters(self, text):
        """智能识别章节，生成章节列表"""
        # 常见章节匹配规则
        chapter_patterns = [
            r'^第[一二三四五六七八九十百千]+章.*$',
            r'^第\d+章.*$',
            r'^Chapter\s*\d+.*$',
        ]

        chapters = []
        lines = text.split('\n')
        for i, line in enumerate(lines):
            line = line.strip()
            if not line:
                continue

            for pattern in chapter_patterns:
                if re.match(pattern, line, re.IGNORECASE):
                    chapters.append({
                        'title': line,
                        'line_number': i
                    })
                    break

        return chapters

    def generate_table_of_contents(self, text):
        """生成目录文本"""
        chapters = self.detect_chapters(text)
        if not chapters:
            return "未识别到章节，无法生成目录\n"

        toc = ["目录\n=====\n\n"]
        for i, chap in enumerate(chapters, 1):
            toc.append(f"{i}. {chap['title']}\n")

        return ''.join(toc)

import requests
import json
class DictionaryLookup:
    """联网查词典工具类"""

    def __init__(self):
        self.history = []
        self.api_url = "https://dict.api.aipyaipy.com/lookup"
        self.search_url = "https://search.api.aipyaipy.com/search"

    def lookup_word(self, word, source="general"):
        """查询单词/成语/生僻字"""
        try:
            # 使用免费开放的词典API
            params = {
                "word": word,
                "source": source
            }
            response = requests.get(self.api_url, params=params, timeout=5)
            if response.status_code == 200:
                result = response.json()

                # 保存到历史记录
                self.history.append({
                    "word": word,
                    "result": result,
                    "type": "lookup"
                })

                return True, result
            else:
                return False, f"查询失败，HTTP状态码: {response.status_code}"

        except Exception as e:
            return False, str(e)

    def web_search(self, query):
        """搜索词义/背景"""
        try:
            params = {
                "q": query
            }
            response = requests.get(self.search_url, params=params, timeout=10)
            if response.status_code == 200:
                result = response.json()

                self.history.append({
                    "word": query,
                    "result": result,
                    "type": "search"
                })

                return True, result
            else:
                return False, f"搜索失败，HTTP状态码: {response.status_code}"

        except Exception as e:
            return False, str(e)

    def format_result(self, result):
        """格式化查询结果为可读文本"""
        output = []

        if "word" in result:
            output.append(f"词语：{result['word']}")

        if "pinyin" in result:
            output.append(f"拼音：{result['pinyin']}")

        if "word_type" in result:
            output.append(f"词性：{result['word_type']}")

        if "definition" in result:
            output.append(f"\n释义：")
            definitions = result['definition']
            if isinstance(definitions, list):
                for i, defin in enumerate(definitions, 1):
                    output.append(f"  {i}. {defin}")
            else:
                output.append(f"  {definitions}")

        if "examples" in result and result['examples']:
            output.append(f"\n例句：")
            for example in result['examples']:
                output.append(f"  - {example}")

        if "abstract" in result:
            output.append(f"\n摘要：{result['abstract']}")

        return '\n'.join(output)

    def get_history(self):
        """获取查询历史"""
        return self.history

    def export_history(self, output_path):
        """导出查询历史"""
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(self.history, f, ensure_ascii=False, indent=2)

