                # 查找HTML内容文件
                for name in zf.namelist():
                    if name.endswith('.html') or name.endswith('.xhtml'):
                        with zf.open(name) as f:
                            soup = BeautifulSoup(f.read(), 'html.parser')
                            # 提取所有文本段落
                            paragraphs = soup.find_all('p')
                            for p in paragraphs:
