        fixed_lines.append('            return\n')
    elif i == 1408:
        fixed_lines.append('        key = "bookmarks_" + hash(self.current_book_path).__str__()\n')
    elif i == 1409:
        fixed_lines.append('        data = getattr(self, \'bookmark_list\', [])\n')
