        fixed_lines.append('            # 也保存到 QSettings 作为备份\n')
    elif i == 1416:
        fixed_lines.append('            self.settings.setValue(key, data)\n')
    elif i == 1417:
        fixed_lines.append('        except Exception as e:\n')
    elif i == 1418:
        fixed_lines.append('            print(f"⚠️ 书签保存失败：{e}")\n')
    else:
        fixed_lines.append(line)
# 重新组合
