                                if text:
                                    text_content.append(text)

            return '\n\n'.join(text_content)
        except ImportError:
            return "错误：需要安装 beautifulsoup4 库才能支持EPUB格式\n" + self._demo_content(file_path)
        except Exception as e:
            return f"读取EPUB文件出错：{str(e)}\n" + self._demo_content(file_path)

    def read_mobi(self, file_path):
        """读取MOBI文件"""
        # 简单处理说明，实际需要依赖mobi库
        return f"[MOBI文件] {os.path.basename(file_path)}\n完整支持需要安装mobi解析库，当前仅占位显示。\n"

