                            data = f.read()
                            b64 = base64.b64encode(data).decode('utf-8')
                            # 设置MIME类型
                            ext = os.path.splitext(img_path)[1].lower()
                            mime = 'image/jpeg'
                            if ext == '.png': mime = 'image/png'
                            elif ext == '.gif': mime = 'image/gif'
                            elif ext == '.svg': mime = 'image/svg+xml'
                            # 替换src为base64
